/* Direct-file interactive figures. No typesetting is generated by JavaScript. */
(function () {
  'use strict';
  var byId = function (id) { return document.getElementById(id); };
  var avg = byId('average-level');
  if (avg) {
    var rect = byId('average-rectangle'), guide = byId('average-guide');
    var averageValue = byId('average-value'), areaValue = byId('average-area');
    function showAverage() {
      var height = Number(avg.value), y = 230 - height * 30;
      rect.setAttribute('y', y); rect.setAttribute('height', 230 - y);
      guide.setAttribute('y1', y); guide.setAttribute('y2', y);
      averageValue.textContent = height.toFixed(1);
      areaValue.textContent = height.toFixed(1);
    }
    avg.addEventListener('input', showAverage);
    byId('average-reset').addEventListener('click', function () { avg.value = 3; showAverage(); });
    showAverage();
  }

  var layer = byId('layer-height');
  if (layer) {
    var slice = byId('moving-slice'), ghost = byId('slice-origin');
    var liftLine = byId('lift-line'), layerValue = byId('layer-value'), liftValue = byId('lift-value');
    var play = byId('layer-play'), pause = byId('layer-pause'), reset = byId('layer-reset');
    var frame = null, progress = 0, lastTime = null;
    function renderLayer() {
      var y = Number(layer.value), origin = 290 - 60 * y, lifted = origin + (50 - origin) * progress;
      ghost.setAttribute('y', origin - 6); slice.setAttribute('y', lifted - 6);
      liftLine.setAttribute('y1', origin); liftLine.setAttribute('y2', 50);
      layerValue.textContent = y.toFixed(1); liftValue.textContent = (4 - y).toFixed(1);
    }
    function stop() { if (frame !== null) cancelAnimationFrame(frame); frame = null; lastTime = null; }
    function tick(time) {
      if (lastTime !== null) progress = Math.min(1, progress + (time - lastTime) / 2400);
      lastTime = time; renderLayer();
      if (progress < 1) frame = requestAnimationFrame(tick); else stop();
    }
    play.addEventListener('click', function () { if (frame !== null) return; if (progress >= 1) progress = 0; frame = requestAnimationFrame(tick); });
    pause.addEventListener('click', stop);
    reset.addEventListener('click', function () { stop(); progress = 0; layer.value = 1.5; renderLayer(); });
    layer.addEventListener('input', function () { stop(); progress = 0; renderLayer(); });
    document.addEventListener('visibilitychange', function () { if (document.hidden) stop(); });
    window.addEventListener('beforeprint', function () { stop(); progress = 0; renderLayer(); });
    renderLayer();
  }

  var lower = byId('probability-lower'), upper = byId('probability-upper');
  if (lower && upper) {
    var shade = byId('probability-shade'), la = byId('density-lower'), lb = byId('density-upper');
    var ca = byId('cdf-lower'), cb = byId('cdf-upper'), segment = byId('cdf-difference');
    var startDot = byId('cdf-dot-a'), endDot = byId('cdf-dot-b');
    function showProbability(changed) {
      var a = Number(lower.value), b = Number(upper.value);
      if (a > b) { if (changed === 'lower') { a = b; lower.value = b; } else { b = a; upper.value = a; } }
      var x = function (t) { return 50 + 340 * t; }, py = function (t) { return 200 - 160 * t; }, fy = function (t) { return 200 - 160 * t * t; };
      shade.setAttribute('points', [x(a)+',200', x(a)+','+py(a), x(b)+','+py(b), x(b)+',200'].join(' '));
      [la, lb].forEach(function (line, i) { var t = i ? b : a; line.setAttribute('x1',x(t)); line.setAttribute('x2',x(t)); line.setAttribute('y1',200); line.setAttribute('y2',py(t)); });
      [ca, cb].forEach(function (line, i) { var t = i ? b : a; line.setAttribute('x1',x(t)); line.setAttribute('x2',x(t)); line.setAttribute('y1',200); line.setAttribute('y2',fy(t)); });
      [byId('cdf-level-a'), byId('cdf-level-b')].forEach(function (line, i) { var t = i ? b : a; line.setAttribute('x1',x(t)); line.setAttribute('y1',fy(t)); line.setAttribute('y2',fy(t)); });
      segment.setAttribute('y1',fy(a)); segment.setAttribute('y2',fy(b));
      startDot.setAttribute('cx',x(a)); startDot.setAttribute('cy',fy(a)); endDot.setAttribute('cx',x(b)); endDot.setAttribute('cy',fy(b));
      byId('lower-value').textContent = a.toFixed(2); byId('upper-value').textContent = b.toFixed(2);
      byId('cdf-a-value').textContent = (a*a).toFixed(4); byId('cdf-b-value').textContent = (b*b).toFixed(4);
      byId('probability-value').textContent = (b*b-a*a).toFixed(4);
    }
    lower.addEventListener('input', function () { showProbability('lower'); });
    upper.addEventListener('input', function () { showProbability('upper'); });
    byId('probability-reset').addEventListener('click', function () { lower.value = .25; upper.value = .75; showProbability(); });
    showProbability();
  }
})();
